INSERT INTO osv_constitution_documents(document_code,title,version,status,jurisdiction_scope,adoption_basis) SELECT 'OSV-GC-001','ÒsánVault Africa Group Constitution & Foundational Charter','0.1','Draft','Continental group; subject to mandatory local law and corporate instruments','Foundational governance architecture; not a substitute for statutory incorporation documents' WHERE NOT EXISTS (SELECT 1 FROM osv_constitution_documents WHERE document_code='OSV-GC-001');
INSERT INTO osv_constitution_principles(document_id,principle_code,title,statement,priority,status) SELECT d.id,'P-01','Human Dignity & Community Stewardship','The Group shall conduct its activities with respect for human dignity, lawful community interests, indigenous and customary rights, cultural heritage and environmental stewardship.',10,'Proposed' FROM osv_constitution_documents d WHERE d.document_code='OSV-GC-001' AND NOT EXISTS (SELECT 1 FROM osv_constitution_principles WHERE principle_code='P-01');
INSERT INTO osv_constitution_principles(document_id,principle_code,title,statement,priority,status) SELECT d.id,'P-02','No Title Without Evidence','No asset, ownership interest, beneficial interest, regulatory status or community right shall be represented as verified without an appropriate evidence trail and jurisdiction-specific review.',20,'Proposed' FROM osv_constitution_documents d WHERE d.document_code='OSV-GC-001' AND NOT EXISTS (SELECT 1 FROM osv_constitution_principles WHERE principle_code='P-02');
INSERT INTO osv_constitution_principles(document_id,principle_code,title,statement,priority,status) SELECT d.id,'P-03','Subsidiary Separation','Each subsidiary, SPV and project vehicle shall retain its separate legal identity, liabilities, assets and governance except where lawful instruments expressly provide otherwise.',30,'Proposed' FROM osv_constitution_documents d WHERE d.document_code='OSV-GC-001' AND NOT EXISTS (SELECT 1 FROM osv_constitution_principles WHERE principle_code='P-03');
INSERT INTO osv_constitution_principles(document_id,principle_code,title,statement,priority,status) SELECT d.id,'P-04','Stewardship Before Extraction','Land, mineral, carbon, cultural and community-linked projects require rights, environmental, social and legal review before commercial representation, acquisition or exploitation.',15,'Proposed' FROM osv_constitution_documents d WHERE d.document_code='OSV-GC-001' AND NOT EXISTS (SELECT 1 FROM osv_constitution_principles WHERE principle_code='P-04');
INSERT INTO osv_constitution_principles(document_id,principle_code,title,statement,priority,status) SELECT d.id,'P-05','Continental Growth With Local Legitimacy','Expansion across Africa shall preserve common principles while respecting each country constitution, laws, customary systems, regulators and legitimate local institutions.',40,'Proposed' FROM osv_constitution_documents d WHERE d.document_code='OSV-GC-001' AND NOT EXISTS (SELECT 1 FROM osv_constitution_principles WHERE principle_code='P-05');
INSERT INTO osv_constitution_principles(document_id,principle_code,title,statement,priority,status) SELECT d.id,'P-06','Accountability & Traceability','Material decisions shall have a defined authority, conflict check, decision record and evidence trail sufficient for independent review.',50,'Proposed' FROM osv_constitution_documents d WHERE d.document_code='OSV-GC-001' AND NOT EXISTS (SELECT 1 FROM osv_constitution_principles WHERE principle_code='P-06');
INSERT INTO osv_constitution_principles(document_id,principle_code,title,statement,priority,status) SELECT d.id,'P-07','Intergenerational Stewardship','The Group shall consider long-term community, environmental, cultural and intergenerational consequences in material asset decisions.',25,'Proposed' FROM osv_constitution_documents d WHERE d.document_code='OSV-GC-001' AND NOT EXISTS (SELECT 1 FROM osv_constitution_principles WHERE principle_code='P-07');
INSERT INTO osv_constitution_articles(document_id,article_number,title,text_body,protection_level,amendment_threshold) SELECT d.id,'I','Name, Nature & Scope','The ÒsánVault Africa Group is a continental institutional platform whose common governance framework coordinates lawful activities across African jurisdictions. Nothing in this Charter overrides mandatory local law.','Foundational','75% Board plus applicable shareholder approval and local-law review' FROM osv_constitution_documents d WHERE d.document_code='OSV-GC-001';
INSERT INTO osv_constitution_articles(document_id,article_number,title,text_body,protection_level,amendment_threshold) SELECT d.id,'II','Purpose & Mission','The Group exists to build durable, transparent and responsible African asset, investment, infrastructure and community-value ecosystems while preserving lawful ownership, stewardship and accountability.','Foundational','75% Board plus applicable shareholder approval' FROM osv_constitution_documents d WHERE d.document_code='OSV-GC-001';
INSERT INTO osv_constitution_articles(document_id,article_number,title,text_body,protection_level,amendment_threshold) SELECT d.id,'III','Rights, Stewardship & Indigenous Protection','Material projects affecting indigenous, customary, community, cultural or protected interests shall pass a jurisdiction-specific rights review. Where law or legitimate community instruments require consultation, consent, benefit-sharing, compensation, grievance or heritage safeguards, the relevant process shall be completed before the Group represents the project as cleared. No internal policy shall extinguish rights that exist under applicable law.','Entrenched','Unanimity of the competent institutional body plus independent legal review; cannot waive mandatory law' FROM osv_constitution_documents d WHERE d.document_code='OSV-GC-001';
INSERT INTO osv_constitution_articles(document_id,article_number,title,text_body,protection_level,amendment_threshold) SELECT d.id,'IV','Ownership, Entities & Asset Separation','The Group shall maintain clear boundaries between the parent, country entities, subsidiaries, SPVs, projects and assets. Ownership and beneficial ownership shall be evidenced. Group-level representation shall not imply title where title is held by another legal person.','Protected','75% Board plus applicable shareholder approval' FROM osv_constitution_documents d WHERE d.document_code='OSV-GC-001';
INSERT INTO osv_constitution_articles(document_id,article_number,title,text_body,protection_level,amendment_threshold) SELECT d.id,'V','Institutions & Separation of Powers','The Group shall operate through constituted bodies including shareholders, the Board, executive management and specialist committees. Authority shall be bounded by mandate, delegation, reserved matters and applicable law.','Protected','75% Board plus applicable shareholder approval' FROM osv_constitution_documents d WHERE d.document_code='OSV-GC-001';
INSERT INTO osv_constitution_articles(document_id,article_number,title,text_body,protection_level,amendment_threshold) SELECT d.id,'VI','Ethics, Conflicts & Recusal','Persons exercising Group authority shall disclose material conflicts. A conflicted decision-maker shall recuse where required by law, policy or the competent body. Retaliation for good-faith reporting of misconduct, corruption, rights violations or material control failures is prohibited.','Protected','75% Board plus applicable shareholder approval and independent review' FROM osv_constitution_documents d WHERE d.document_code='OSV-GC-001';
INSERT INTO osv_constitution_articles(document_id,article_number,title,text_body,protection_level,amendment_threshold) SELECT d.id,'VII','Capital, Investment & Risk','Capital shall be deployed only within approved authority, risk limits and applicable law. Material investment, leverage, guarantee, related-party and concentration decisions shall follow the Group authority matrix and reserved-matter rules.','Protected','75% Board plus applicable shareholder approval' FROM osv_constitution_documents d WHERE d.document_code='OSV-GC-001';
INSERT INTO osv_constitution_articles(document_id,article_number,title,text_body,protection_level,amendment_threshold) SELECT d.id,'VIII','Transparency, Audit & Evidence','Material institutional decisions, ownership records, conflicts, approvals and rights reviews shall be traceable. Audit and risk functions shall have sufficient access to test the integrity of the Group records and controls.','Protected','75% Board plus applicable shareholder approval' FROM osv_constitution_documents d WHERE d.document_code='OSV-GC-001';
INSERT INTO osv_constitution_articles(document_id,article_number,title,text_body,protection_level,amendment_threshold) SELECT d.id,'IX','Dispute Resolution & Grievance','The Group shall maintain accessible grievance and dispute pathways appropriate to the jurisdiction and affected parties. Local statutory forums and lawful community mechanisms shall not be displaced merely by internal procedures.','Protected','75% Board plus applicable shareholder approval and legal review' FROM osv_constitution_documents d WHERE d.document_code='OSV-GC-001';
INSERT INTO osv_constitution_articles(document_id,article_number,title,text_body,protection_level,amendment_threshold) SELECT d.id,'X','Continental Expansion & Accession','A new country may join the Group architecture through a documented accession process after jurisdictional, regulatory, tax, ownership, land-rights and local-governance review. Local entities shall adopt or align with common principles without conflicting with mandatory local law.','Protected','75% Board plus applicable shareholder approval and local-law review' FROM osv_constitution_documents d WHERE d.document_code='OSV-GC-001';
INSERT INTO osv_constitution_articles(document_id,article_number,title,text_body,protection_level,amendment_threshold) SELECT d.id,'XI','Emergency Powers','Emergency authority may be exercised only to protect life, assets, data, institutional continuity or legal compliance, must be narrowly scoped, documented and reviewed after the event, and may not permanently bypass entrenched rights protections.','Entrenched','Unanimity of competent body for amendment plus independent legal review' FROM osv_constitution_documents d WHERE d.document_code='OSV-GC-001';
INSERT INTO osv_constitution_articles(document_id,article_number,title,text_body,protection_level,amendment_threshold) SELECT d.id,'XII','Amendment, Succession & Dissolution','Amendments shall follow the thresholds applicable to the provision affected. Dissolution, restructuring or succession shall preserve lawful third-party rights, creditor rights, community obligations and statutory duties.','Foundational','75% Board plus applicable shareholder approval and local-law review' FROM osv_constitution_documents d WHERE d.document_code='OSV-GC-001';
INSERT INTO osv_constitution_reserved(document_id,matter_code,title,approval_route,threshold,protected_rights_gate,independent_review) SELECT d.id,'CR-001','Amend Entrenched Rights Protections','Competent Board + applicable shareholders + independent legal review','Unanimous or higher threshold required by applicable law; cannot waive mandatory law',true,true FROM osv_constitution_documents d WHERE d.document_code='OSV-GC-001';
INSERT INTO osv_constitution_reserved(document_id,matter_code,title,approval_route,threshold,protected_rights_gate,independent_review) SELECT d.id,'CR-002','Acquire or Dispose of Protected / Community-Linked Asset','Board + Ethics & Stewardship Committee','As required by law and Group reserved-matter matrix',true,true FROM osv_constitution_documents d WHERE d.document_code='OSV-GC-001';
INSERT INTO osv_constitution_reserved(document_id,matter_code,title,approval_route,threshold,protected_rights_gate,independent_review) SELECT d.id,'CR-003','Enter a New Country','Board + Legal/Compliance + relevant local governance body','Supermajority under adopted authority matrix',true,true FROM osv_constitution_documents d WHERE d.document_code='OSV-GC-001';