CREATE TABLE IF NOT EXISTS osv_constitution_documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), document_code text NOT NULL UNIQUE, title text NOT NULL, version text NOT NULL, status text NOT NULL DEFAULT 'Draft', jurisdiction_scope text NOT NULL, effective_date date, adoption_basis text, evidence_reference text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS osv_constitution_articles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), document_id uuid REFERENCES osv_constitution_documents(id) ON DELETE CASCADE, article_number text NOT NULL, title text NOT NULL, text_body text NOT NULL, protection_level text NOT NULL DEFAULT 'Ordinary', amendment_threshold text, status text NOT NULL DEFAULT 'Draft', UNIQUE(document_id,article_number));
CREATE TABLE IF NOT EXISTS osv_constitution_principles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), document_id uuid REFERENCES osv_constitution_documents(id) ON DELETE CASCADE, principle_code text NOT NULL, title text NOT NULL, statement text NOT NULL, priority integer NOT NULL DEFAULT 100, status text NOT NULL DEFAULT 'Proposed');
CREATE TABLE IF NOT EXISTS osv_constitution_reserved (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), document_id uuid REFERENCES osv_constitution_documents(id) ON DELETE CASCADE, matter_code text NOT NULL, title text NOT NULL, approval_route text NOT NULL, threshold text NOT NULL, protected_rights_gate boolean NOT NULL DEFAULT false, independent_review boolean NOT NULL DEFAULT false, status text NOT NULL DEFAULT 'Proposed');
CREATE TABLE IF NOT EXISTS osv_constitution_amendments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), document_id uuid REFERENCES osv_constitution_documents(id) ON DELETE CASCADE, amendment_number text NOT NULL, proposed_text text NOT NULL, proposer_reference text, approval_route text, vote_result text, effective_date date, status text NOT NULL DEFAULT 'Proposed', evidence_reference text);
CREATE TABLE IF NOT EXISTS osv_constitution_interpretations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), document_id uuid REFERENCES osv_constitution_documents(id) ON DELETE CASCADE, article_reference text NOT NULL, question text NOT NULL, interpretation text NOT NULL, issued_by text, issued_date date, binding_level text NOT NULL DEFAULT 'Advisory', status text NOT NULL DEFAULT 'Draft', evidence_reference text);
CREATE TABLE IF NOT EXISTS osv_constitution_accessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), document_id uuid REFERENCES osv_constitution_documents(id) ON DELETE CASCADE, country_name text NOT NULL, iso_code text, accession_type text NOT NULL, local_instrument_reference text, local_law_review_status text NOT NULL DEFAULT 'Required', effective_date date, status text NOT NULL DEFAULT 'Proposed', evidence_reference text);
